sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    var panReqId = current.getValue('nt_request');
    if (!panReqId) return;

    // Check if any sibling site records under this PAN request are still pending or failed
    var pendingPanRows = new GlideRecord('x_birl3_clm_clm_servicenow_to_sap_send_back');
    var qcPan = pendingPanRows.addQuery('nt_request', panReqId);
    pendingPanRows.addQuery('u_status', '!=', 'Success');
    pendingPanRows.setLimit(1);
    pendingPanRows.query();

    // Proceed only if all child site writeback rows in this PAN batch have succeeded
    if (!pendingPanRows.hasNext()) {
        // 1. Update parent NT PAN Request state to 3
        var panGr = new GlideRecord('x_birl3_clm_nt_pan_request');
        if (panGr.get(panReqId)) {
            panGr.setValue('state', '3');
            panGr.update();
        }

        // 2. Update all child Site Requests for this PAN to approved
        var siteGr = new GlideRecord('x_birl3_clm_nt_site_request');
        siteGr.addQuery('pan_request', panReqId);
        siteGr.query();
        while (siteGr.next()) {
            siteGr.setValue('approval', 'approved');
            siteGr.update();
        }

        gs.info('CLM SAP Writeback Sync: NT PAN Request ' + panReqId + ' set to State 3 and child sites marked Approved.');
    }

})(current, previous);
